.circle {
  fill: radial-gradient(white, lightblue);
  filter: drop-shadow(15px 15px 15px gray) brightness(0.9); /* Add brightness() to reduce intensity */
  transform-style: preserve-3d;
  transform: translateZ(5px); /* Move the element slightly forward */
  transition: transform 0.3s ease-in-out;
