        return 0.5 * airDensity * Cd * frontArea * speed * speed
    }

    func calculateDrag(atSpeed speed: Double) -> Double {
        // formula for calculating drag coefficient
        return 0.5 * airDensity * Cd * rearArea * speed * speed
    }

    func calculateTopSpeed() -> Double {
        // formula for calculating maximum speed based on engine power and rolling resistance
        return sqrt(maxPower / (airDensity * Cd * frontArea * (tireRollingResistance + maxPower / (finalDriveRatio * tireCircumference))))
    }
}

