 ```matlab
 morseCode = { '.', '-', '/' };    % Define Morse Code symbols

 % Create a lookup table for easy access to Morse Code
 morseLookup = cell(26 + 10, 1, '{' );
 for I = 65:65:90            % Uppercase letters
     morseLookup{i} = morseCode(strfind(strrep(['. ', '-'], string(i), '.' ), '.' ));
 end
 for I = 97:97:122           % Lowercase letters
     morseLookup{i+26} = morseCode(strfind(strrep(['. ', '-'], string(i), '.' ), '.' ));
 end
 for I = 48:48:57           % Numbers
     morseLookup{i+52} = {'-----', '.', '..--', '--...', '....-', '.....', '-.--.-', '--..-', '-----.'};
 end

 % Prompt user for input phrase
 inputStr = input('Enter a phrase: ', 's');

 % Convert input to uppercase and create empty output string
 inputStr = upper(inputStr);
 outputStr = '';

 % Loop through input string and add corresponding Morse Code segments
 for I = 1:length(inputStr)
     charCode = int(inputStr(i));
     if charCode >= 65 && charCode <= 90 || charCode >= 97 && charCode <= 122 || charCode >= 48 && charCode <= 57
         outputStr = [outputStr, morseLookup{charCode}(:)' ];
     else                       % Non-printable characters are skipped
         outputStr = [outputStr, ' ' ];
     end
 end

 % Print output Morse Code string
 disp(outputStr);
