    nlohmann::json json;
    jsonFile >> json;
    std::vector<int> arr(json["array"].begin(), json["array"].end());
    return arr;
}

// Function to write JSON data to file
void writeJSONData(std::vector<int> arr) {
    nlohmann::json json;
    json["array"] = arr;
    std::ofstream jsonFile("output.json");
    jsonFile << std::setw(4) << json;
}

int main() {
    // Read JSON data
    std::vector<int> arr = readJSONData();

    // Sort the array using bubble sort
    bubbleSort(arr.data(), arr.size());

    // Write sorted JSON data
    writeJSONData(arr);

    return 0;
}
```

