        {
            BaseUrl = baseUrl;
        }

        protected async Task<TResult> SendRequestAsync<TResult>(HttpMethod method, string endpoint, object body = null, CancellationToken cancellationToken = default)
        {
            using var client = CreateHttpClient();
            var requestUri = new Uri($"{BaseUrl}{endpoint}");
            var request = new HttpRequestMessage(method, requestUri);

            if (body != null)
            {
                request.Content = new StringContent(JsonConvert.SerializeObject(body), UnicodeEncoding.UTF8, "application/json");
            }

            request.Headers.Add("Authorization", $"Bearer {AccessToken}");
            request.Headers.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

            using var response = await client.SendAsync(request, cancellationToken).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();

            return JsonConvert.DeserializeObject<TResult>(await response.Content.ReadAsStringAsync().ConfigureAwait(false));
        }

